import React from 'react';
import {AbsoluteFill, Easing, interpolate} from 'remotion';
import {useS, en, clamp, DUR, T} from './kit';

const W = 1080;
const H = 1920;

// Momentos clave del guion
const CAMINO_CUESTA = en('camino');
const MONTES = en('montes');
const SOCORRO = en('socorro');
const CIELOS = en('cielos');
const RESBALADERO = en('resbaladero');
const GUARDA = en('guarda');
const PROBLEMA = en('problema');
const PLANO = en('plano');
const RESBALARAN = en('resbalarán');
const DORMIDO = en('dormido');
const AMEN = en('amén');

const Cielo: React.FC<{s: number}> = ({s}) => {
  const t_atardecer = interpolate(s, [MONTES, CIELOS + 2], [0, 1], clamp);
  const arriba = interpolate(t_atardecer, [0, 1], [40, 15], clamp); // Azul a profundo
  const abajo = interpolate(t_atardecer, [0, 1], [180, 40], clamp); // Naranja a oscuro
  return (
    <AbsoluteFill style={{
      background: `linear-gradient(180deg, hsl(210, 80%, ${arriba}%) 0%, hsl(30, 90%, ${abajo}%) 100%)`
    }} />
  );
};

const Estrellas: React.FC<{s: number}> = ({s}) => {
  const vis = interpolate(s, [CIELOS, CIELOS + 5], [0, 0.8], clamp);
  return (
    <AbsoluteFill style={{opacity: vis}}>
      {Array.from({length: 60}).map((_, i) => {
        const x = (i * 197) % W;
        const y = (i * 313) % (H * 0.6);
        const r = 1 + (i % 3);
        const b = 0.3 + 0.7 * Math.abs(Math.sin(s * 0.5 + i));
        return <div key={i} style={{position: 'absolute', left: x, top: y, width: r * 2, height: r * 2, borderRadius: '50%', background: '#fff', opacity: b}} />;
      })}
    </AbsoluteFill>
  );
};

const Montes: React.FC<{s: number}> = ({s}) => {
  const paralaje = interpolate(s, [0, DUR], [0, -150], clamp);
  const mirar_arriba = interpolate(s, [MONTES, MONTES + 2], [0, 300], clamp);

  return (
    <AbsoluteFill style={{top: mirar_arriba}}>
      {/* Montaña lejana */}
      <svg width={W + 400} height={1200} style={{position: 'absolute', left: -200 + paralaje * 0.3, bottom: 400}} viewBox={`0 0 ${W + 400} 1200`}>
        <path d={`M0 1200 L0 800 L300 500 L600 700 L900 300 L1480 900 L1480 1200 Z`} fill="#1a1c3a" />
        <path d={`M300 500 L350 550 L280 580 Z M900 300 L980 380 L850 420 Z`} fill="rgba(255,255,255,0.15)" />
      </svg>
      {/* Montaña media */}
      <svg width={W + 400} height={1000} style={{position: 'absolute', left: -200 + paralaje * 0.6, bottom: 200}} viewBox={`0 0 ${W + 400} 1000`}>
        <path d={`M0 1000 L0 600 L400 400 L800 650 L1200 350 L1480 700 L1480 1000 Z`} fill="#0d0e25" />
        <path d={`M400 400 L460 480 L360 500 Z M1200 350 L1280 450 L1150 480 Z`} fill="rgba(255,255,255,0.08)" />
      </svg>
    </AbsoluteFill>
  );
};

const Camino: React.FC<{s: number}> = ({s}) => {
  const progreso = interpolate(s, [0, DUR], [0, 1000]);
  const resbalar = interpolate(s, [RESBALADERO, RESBALADERO + 0.3, RESBALADERO + 0.6], [0, 15, 0], clamp);
  const firme = interpolate(s, [RESBALARAN, RESBALARAN + 1], [0, 1], clamp);

  return (
    <AbsoluteFill style={{top: 1300 + resbalar}}>
      <svg width={W} height={700} viewBox={`0 0 ${W} 700`} style={{position: 'absolute'}}>
        <path 
          d="M540 0 C 400 200, 700 400, 540 700" 
          stroke={firme > 0 ? `rgba(255, 215, 100, ${0.3 + firme * 0.4})` : "rgba(255,255,255,0.2)"} 
          strokeWidth={120} 
          fill="none" 
        />
        <path 
          d="M540 0 C 400 200, 700 400, 540 700" 
          stroke="rgba(0,0,0,0.2)" 
          strokeWidth={140} 
          fill="none" 
          strokeDasharray="20 40"
          strokeDashoffset={progreso}
        />
      </svg>
      {/* Figura humana silueta caminando */}
      <div style={{
        position: 'absolute', 
        left: 540 + Math.sin(s * 2) * 20, 
        top: 250 + Math.cos(s * 4) * 10,
        transform: `translateX(-50%)`,
        opacity: interpolate(s, [RESBALADERO, RESBALADERO + 0.5], [1, 0.8], clamp)
      }}>
        <svg width={80} height={160} viewBox="0 0 80 160">
          <circle cx={40} cy={25} r={20} fill="#050510" />
          <path d="M20 50 Q 40 45 60 50 L 70 120 L 10 120 Z" fill="#050510" />
          {/* Piernas caminando */}
          <line x1={30} y1={120} x2={30 + Math.sin(s * 10) * 20} y2={155} stroke="#050510" strokeWidth={12} strokeLinecap="round" />
          <line x1={50} y1={120} x2={50 + Math.sin(s * 10 + Math.PI) * 20} y2={155} stroke="#050510" strokeWidth={12} strokeLinecap="round" />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

const OjoDivino: React.FC<{s: number}> = ({s}) => {
  const vis = interpolate(s, [GUARDA, GUARDA + 1.5, DORMIDO + 1, DORMIDO + 2.5], [0, 1, 1, 0], clamp);
  const pulso = 1 + Math.sin(s * 1.5) * 0.05;
  return (
    <div style={{
      position: 'absolute', 
      left: W/2, 
      top: 400, 
      transform: `translate(-50%, -50%) scale(${pulso})`,
      opacity: vis * 0.6,
      filter: 'blur(30px)'
    }}>
      <div style={{width: 600, height: 300, borderRadius: '50%', background: 'radial-gradient(circle, #fff 0%, #ffd84d 40%, transparent 80%)'}} />
    </div>
  );
};

const BrilloSocorro: React.FC<{s: number}> = ({s}) => {
  const t = interpolate(s, [SOCORRO, SOCORRO + 1], [0, 1], clamp) * interpolate(s, [SOCORRO + 2, SOCORRO + 3], [1, 0], clamp);
  return (
    <AbsoluteFill style={{opacity: t, pointerEvents: 'none'}}>
      <div style={{
        position: 'absolute', 
        left: W/2, 
        top: H/2, 
        width: 800, 
        height: 800, 
        transform: 'translate(-50%, -50%)',
        background: 'radial-gradient(circle, rgba(255,255,255,0.4) 0%, transparent 70%)',
        mixBlendMode: 'screen'
      }} />
    </AbsoluteFill>
  );
};

const MoralejaLuz: React.FC<{s: number}> = ({s}) => {
  const t = interpolate(s, [PROBLEMA, PROBLEMA + 1], [0, 1], clamp);
  return (
    <AbsoluteFill style={{
      background: `radial-gradient(circle at 50% 50%, rgba(255,216,77,${0.1 * t}) 0%, transparent 80%)`,
      opacity: t
    }} />
  );
};

export const Escena: React.FC = () => {
  const {s} = useS();

  // Movimiento de cámara suave
  const zoom = interpolate(s, [0, MONTES, RESBALADERO, AMEN], [1.1, 1.3, 1.5, 1.2], clamp);
  const camY = interpolate(s, [0, MONTES, CIELOS, RESBALADERO, AMEN], [0, -200, -400, 200, 0], clamp);

  return (
    <AbsoluteFill style={{backgroundColor: '#050510', overflow: 'hidden'}}>
      <div style={{
        transform: `scale(${zoom}) translateY(${camY}px)`, 
        transformOrigin: 'center center',
        width: '100%',
        height: '100%'
      }}>
        <Cielo s={s} />
        <Estrellas s={s} />
        <Montes s={s} />
        <OjoDivino s={s} />
        <Camino s={s} />
        <BrilloSocorro s={s} />
        <MoralejaLuz s={s} />
      </div>

      {/* Viñeta de paz */}
      <AbsoluteFill style={{
        background: 'radial-gradient(circle, transparent 40%, rgba(0,0,0,0.6) 100%)'
      }} />

      {/* Partículas de luz constantes */}
      {Array.from({length: 25}).map((_, i) => {
        const x = (i * 137) % W;
        const y = H - ((i * 251 + s * 40) % (H + 200));
        return (
          <div key={i} style={{
            position: 'absolute', 
            left: x, 
            top: y, 
            width: 4, 
            height: 4, 
            borderRadius: '50%', 
            background: '#fff', 
            opacity: 0.3,
            filter: 'blur(1px)'
          }} />
        );
      })}
    </AbsoluteFill>
  );
};
